window.products.push({"id":728569,"name":"Agave Pineapple Aromatique Reed and Ceramic Diffuser Oil Refills - 4oz","category":"homeandappliances","retail price":19.5,"sale price":null,"image":"https://m.media-amazon.com/images/I/21Wl6cftbOL._AC_.jpg","description":"AGAVE PINEAPPLE Aromatique Reed and Ceramic Diffuser Oil Refills - 4oz A blend of Pineapple, Agave, and Rosewood Aromatique Diffusers Refills work great in both Reed Diffusers and Ceramic Diffusers. These Diffusers do not use any heat or fire. For Ceramic Diffusers, just pour the fragrance into the lamp with the enclosed funnel and put the decorative diffuser top on the lamp and let the fragrance slowly fill the room. For Reed Diffusers, pour the fragrance into the vessel and insert a new set of reeds. Each bottle holds 4 ounces of fragrance.","images":["https://m.media-amazon.com/images/I/21Wl6cftbOL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Aromatique","source_asin":"B078T25KGL","category_path":"Home & Kitchen"},"sku":"BM-728569","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B078T25KGL","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B078T25KGL","price_pending":true,"merchant_ready":false});
